// 把每個關鍵字拆成獨立 item，後面節點會逐一掃描
const cfg = $json;
return cfg.keywords.map(kw => ({
  json: {
    keyword: kw,
    apify_token: cfg.apify_token,
    claude_api_key: cfg.claude_api_key,
    google_sheet_id: cfg.google_sheet_id,
    line_token: cfg.line_token,
    alert_threshold: cfg.alert_threshold,
    max_items_per_keyword: cfg.max_items_per_keyword,
    apify_actor_id: cfg.apify_actor_id
  }
}));

// 把 Apify 回傳的貼文陣列展開成 n8n items，並補上來源關鍵字
const keyword = $('🔄 拆分關鍵字').item.json.keyword;
const posts = Array.isArray($json) ? $json : ($json.body || []);

return posts.map(p => {
  const user = p.user || p.author || {};
  return {
    json: {
      platform_id: String(p.userId || user.id || user.username || p.id || ''),
      username: user.username || p.username || '',
      display_name: user.fullName || user.full_name || user.displayName || '',
      profile_url: user.profileUrl || (user.username ? `https://www.threads.net/@${user.username}` : ''),
      follower_count: Number(user.followerCount || user.followers || 0),
      trigger_keyword: keyword,
      post_text: (p.text || p.caption || '').slice(0, 500),
      post_url: p.url || p.postUrl || '',
      posted_at: p.publishedAt || p.timestamp || '',
      raw: p
    }
  };
}).filter(it => it.json.platform_id);

// 把現有 sheet 資料的 platform_id 拿出來，過濾掉已存在的用戶
const existingRows = $items('📋 Google Sheet 去重查詢').map(i => i.json);
const seen = new Set(existingRows.map(r => String(r.platform_id || '')));

const posts = $items('🧹 整理貼文資料').map(i => i.json);
const fresh = posts.filter(p => !seen.has(String(p.platform_id)));

return fresh.map(p => ({ json: p }));

