// 解析 Claude 回應 → 把分析結果合併進原 post item
const post = $('🔍 過濾新用戶').item.json;
const resp = $json;

const rawText = (resp?.content?.[0]?.text || '').trim();

let parsed = {
  customer_type: '',
  spend_level: 'C',
  conversion_score: 1,
  intent_signals: [],
  best_contact_angle: '',
  risk_flags: [],
  analysis_reason: '解析失敗'
};

try {
  const m = rawText.match(/\{[\s\S]*\}/);
  if (m) parsed = { ...parsed, ...JSON.parse(m[0]) };
} catch (e) {
  parsed.analysis_reason = '解析失敗：' + e.message;
}

const score = Math.max(1, Math.min(10, parseInt(parsed.conversion_score, 10) || 1));
const now = new Date().toISOString();

return [{
  json: {
    platform_id: post.platform_id,
    username: post.username,
    display_name: post.display_name,
    profile_url: post.profile_url,
    follower_count: post.follower_count,
    trigger_keyword: post.trigger_keyword,
    post_text: post.post_text,
    customer_type: parsed.customer_type,
    spend_level: parsed.spend_level,
    conversion_score: score,
    intent_signals: Array.isArray(parsed.intent_signals) ? parsed.intent_signals.join('｜') : String(parsed.intent_signals || ''),
    best_contact_angle: parsed.best_contact_angle,
    risk_flags: Array.isArray(parsed.risk_flags) ? parsed.risk_flags.join('｜') : String(parsed.risk_flags || ''),
    analysis_reason: parsed.analysis_reason,
    status: '潛在',
    contact_count: 0,
    scraped_at: now,
    last_updated: now,
    is_high_priority: score >= ($('⚙️ 系統設定（改這裡）').item.json.alert_threshold || 7)
  }
}];

