// 彙總本次掃描的統計數據
const all = $items('📦 解析 Claude 回應').map(i => i.json);
if (all.length === 0) {
  return [{ json: {
    scan_time: new Date().toISOString(),
    total_scanned: 0,
    high_priority_count: 0,
    avg_conversion_score: 0,
    keywords_covered: '',
    status: '無新資料'
  }}];
}

const threshold = $('⚙️ 系統設定（改這裡）').item.json.alert_threshold || 7;
const totalScore = all.reduce((s, r) => s + (Number(r.conversion_score) || 0), 0);
const keywords = [...new Set(all.map(r => r.trigger_keyword))];

return [{ json: {
  scan_time: new Date().toISOString(),
  total_scanned: all.length,
  high_priority_count: all.filter(r => r.conversion_score >= threshold).length,
  avg_conversion_score: Math.round((totalScore / all.length) * 100) / 100,
  keywords_covered: keywords.join('｜'),
  status: '完成'
}}];
